/* Vendored minimal Chart.js stub.
 *
 * The verification contract requires that the dashboard not pull
 * Chart.js from a runtime CDN. This file is the vendored asset
 * referenced from index.html. It exposes a tiny ``Chart`` constructor
 * sufficient for the demo dashboard to call ``new Chart(ctx, config)``
 * without network access. Replace with the upstream
 * ``chart.umd.min.js`` build for production.
 */
(function (root) {
  "use strict";

  function clear(canvas) {
    var ctx = canvas.getContext && canvas.getContext("2d");
    if (!ctx) return null;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    return ctx;
  }

  function drawBars(canvas, labels, data) {
    var ctx = clear(canvas);
    if (!ctx) return;
    var w = canvas.width;
    var h = canvas.height;
    var max = Math.max.apply(null, data.concat([1]));
    var n = data.length || 1;
    var bw = w / (n * 1.5);
    ctx.fillStyle = "#2b6cb0";
    ctx.font = "12px sans-serif";
    for (var i = 0; i < data.length; i++) {
      var x = (i + 0.25) * (w / n);
      var bh = (data[i] / max) * (h - 30);
      ctx.fillRect(x, h - 20 - bh, bw, bh);
      ctx.fillStyle = "#1a202c";
      ctx.fillText(String(labels[i] || ""), x, h - 5);
      ctx.fillStyle = "#2b6cb0";
    }
  }

  function drawLine(canvas, labels, data) {
    var ctx = clear(canvas);
    if (!ctx) return;
    var w = canvas.width;
    var h = canvas.height;
    var max = Math.max.apply(null, data.concat([1]));
    var n = data.length || 1;
    ctx.strokeStyle = "#2f855a";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (var i = 0; i < data.length; i++) {
      var x = (i / Math.max(1, n - 1)) * (w - 20) + 10;
      var y = h - 20 - (data[i] / max) * (h - 40);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.fillStyle = "#1a202c";
    ctx.font = "12px sans-serif";
    for (var j = 0; j < labels.length; j++) {
      var lx = (j / Math.max(1, n - 1)) * (w - 20) + 10;
      ctx.fillText(String(labels[j] || ""), lx - 10, h - 5);
    }
  }

  function Chart(target, config) {
    var canvas = target && target.canvas ? target.canvas : target;
    var type = (config && config.type) || "bar";
    var data = (config && config.data) || { labels: [], datasets: [{ data: [] }] };
    var labels = data.labels || [];
    var values = (data.datasets && data.datasets[0] && data.datasets[0].data) || [];
    if (type === "line") drawLine(canvas, labels, values);
    else drawBars(canvas, labels, values);
    this.canvas = canvas;
    this.config = config;
  }

  Chart.prototype.destroy = function () {
    if (this.canvas) clear(this.canvas);
  };

  root.Chart = Chart;
})(typeof window !== "undefined" ? window : this);
